      try {
        setSubmittingReview(true);
        setReviewsError(null);

        if (!localUserReview.rating) {
          setReviewsError('Please provide a rating');
          return;
        }

        const reviewData = {
          beerId: selectedBeer._id,
          rating: localUserReview.rating,
          notes: localUserReview.notes
        };

