                      </div>
                      <div className="flex-1">
                        <h4 className="font-semibold text-gray-900">{review.beer?.name}</h4>
                        <p className="text-sm text-gray-600">{review.beer?.brewery}</p>
                        <div className="flex items-center gap-2 mt-1">
                          <StarRating rating={review.rating} size="w-4 h-4" />
                          <span className="text-sm font-semibold">({review.rating}/5)</span>
                        </div>
                      </div>
                    </div>
                  ))}
                </div>
              ) : (
                <p className="text-gray-600 text-center py-8">No highly rated beers yet. Start reviewing to see your favorites here!</p>
              )}
            </div>

            {/* Recent Reviews */}
            <div className="bg-white rounded-xl shadow-xl p-8 border-4 border-gray-200">
              <h3 className="text-2xl font-bold text-gray-900 mb-6 font-serif">📝 Recent Reviews</h3>
              {userReviews.length > 0 ? (
                <div className="space-y-4 max-h-96 overflow-y-auto">
                  {userReviews.slice(0, 5).map((review) => (
                    <div key={review._id} className="border-b border-gray-200 pb-4">
                      <div className="flex items-center justify-between mb-2">
                        <h4 className="font-semibold text-gray-900">{review.beer?.name}</h4>
                        <StarRating rating={review.rating} size="w-4 h-4" />
                      </div>
                      <p className="text-sm text-gray-600 mb-1">{review.beer?.brewery}</p>
                      {review.notes && (
                        <p className="text-sm text-gray-700 italic">"{review.notes}"</p>
                      )}
                      <p className="text-xs text-gray-500 mt-2">
                        {new Date(review.createdAt).toLocaleDateString()}
                      </p>
                    </div>
                  ))}
                  {userReviews.length > 5 && (
                    <button className="text-red-600 hover:text-red-800 font-semibold text-sm">
                      View all {userReviews.length} reviews →
                    </button>
                  )}
                </div>
              ) : (
                <p className="text-gray-600 text-center py-8">No reviews yet. Start reviewing beers to see them here!</p>
              )}
            </div>
          </div>

          {/* My Added Beers */}
          {userBeers.length > 0 && (
            <div className="bg-white rounded-xl shadow-xl p-8 mt-8 border-4 border-gray-200">
              <h3 className="text-2xl font-bold text-gray-900 mb-6 font-serif">🍺 Beers I've Added</h3>
              <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
                {userBeers.map((beer) => (
                  <BeerCard key={beer._id} beer={beer} onClick={handleBeerSelect} />
                ))}
              </div>
            </div>
          )}
        </div>
      </div>
    );
  };

  const renderPage = () => {
    switch(currentPage) {
      case 'home':
        return <HomePage />;
      case 'beers':
        return <BeersPage />;
      case 'add':
        return <AddBeerPage />;
      case 'login':
        return <LoginPage />;
      case 'register':
        return <RegisterPage />;
      case 'beer-detail':
        return <BeerDetailPage />;
      case 'profile':
        return <ProfilePage />;
      default:
        return <HomePage />;
    }
  };

  return (
    <div className="min-h-screen bg-gradient-to-br from-gray-50 to-white">
      <Navigation />
      {renderPage()}
    </div>
  );
};

export default BeerReviewApp;
